-- =====================================================================
-- PSP fraud engine, sanctions/PEP screening, AML monitoring
-- GENERATED by tools/codegen/gen_ddl.py from risk.spec
-- (same specs as the JPA entities). Edit the spec, regenerate, never hand-edit.
-- =====================================================================

-- A configurable fraud rule. Types: VELOCITY_COUNT, VELOCITY_AMOUNT, SINGLE_AMOUNT, NEW_COUNTERPARTY_AMOUNT, NIGHT_AMOUNT, DISTINCT_COUNTERPARTIES.
CREATE TABLE psp_risk_rules (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    rule_code                    VARCHAR(60) NOT NULL,
    description                  VARCHAR(300) NOT NULL,
    rule_type                    VARCHAR(40) NOT NULL,
    applies_to                   VARCHAR(200) NOT NULL,
    window_minutes               INT NOT NULL DEFAULT 0,
    threshold_count              INT NOT NULL DEFAULT 0,
    threshold_amount_usd_minor   BIGINT NOT NULL DEFAULT 0,
    score                        INT NOT NULL DEFAULT 0,
    action                       VARCHAR(10) NOT NULL,
    enabled                      BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_risk_rule_code UNIQUE (rule_code)
);

-- Hard blocks: MSISDN, DEVICE, IP, NATIONAL_ID (blind index), ACCOUNT. Checked before any rule.
CREATE TABLE psp_risk_blocklist (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    entry_type                   VARCHAR(20) NOT NULL,
    entry_value                  VARCHAR(120) NOT NULL,
    reason                       VARCHAR(500) NOT NULL,
    added_by                     VARCHAR(120) NOT NULL,
    expires_at                   DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_block_value UNIQUE (entry_type,entry_value)
);

-- Every assessed transaction, for velocity features and model training. Kept 13 months.
CREATE TABLE psp_risk_events (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    txn_type                     VARCHAR(40) NOT NULL,
    channel                      VARCHAR(20),
    subject_ref                  VARCHAR(60) NOT NULL,
    counterparty_ref             VARCHAR(120),
    amount_usd_minor             BIGINT NOT NULL DEFAULT 0,
    currency                     VARCHAR(3) NOT NULL,
    amount_minor                 BIGINT NOT NULL DEFAULT 0,
    score                        INT NOT NULL DEFAULT 0,
    decision                     VARCHAR(10) NOT NULL,
    reasons                      VARCHAR(1000),
    created_at                   DATETIME(6) NOT NULL,
    INDEX idx_rev_subject (subject_ref,created_at),
    INDEX idx_rev_counterparty (counterparty_ref,created_at)
);

-- A fraud or AML case for investigation.
CREATE TABLE psp_risk_cases (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    case_ref                     VARCHAR(40) NOT NULL,
    case_type                    VARCHAR(20) NOT NULL,
    subject_type                 VARCHAR(20) NOT NULL,
    subject_ref                  VARCHAR(120) NOT NULL,
    trigger_ref                  VARCHAR(120),
    score                        INT NOT NULL DEFAULT 0,
    reasons                      TEXT,
    status                       VARCHAR(30) NOT NULL,
    assigned_to                  VARCHAR(120),
    outcome_note                 VARCHAR(2000),
    closed_by                    VARCHAR(120),
    closed_at                    DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_risk_cases_case_ref UNIQUE (case_ref),
    INDEX idx_case_status (status,created_at),
    INDEX idx_case_subject (subject_ref)
);

-- One person / entity on a sanctions or PEP list.
CREATE TABLE psp_sanctions_entries (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    list_code                    VARCHAR(20) NOT NULL,
    external_id                  VARCHAR(80) NOT NULL,
    entry_type                   VARCHAR(20) NOT NULL,
    primary_name                 VARCHAR(400) NOT NULL,
    normalised_name              VARCHAR(400) NOT NULL,
    aliases                      TEXT,
    nationality                  VARCHAR(200),
    date_of_birth                VARCHAR(100),
    programme                    VARCHAR(200),
    active                       BOOLEAN NOT NULL DEFAULT FALSE,
    list_version                 VARCHAR(64) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    INDEX idx_sanc_list (list_code,active),
    CONSTRAINT uq_sanc_ext UNIQUE (list_code,external_id)
);

-- Audit of each list refresh: which version was in force when a screening was done.
CREATE TABLE psp_sanctions_list_versions (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    list_code                    VARCHAR(20) NOT NULL,
    sha256                       VARCHAR(64) NOT NULL,
    entry_count                  INT NOT NULL DEFAULT 0,
    source                       VARCHAR(300),
    status                       VARCHAR(20) NOT NULL,
    error                        VARCHAR(1000),
    fetched_at                   DATETIME(6) NOT NULL,
    INDEX idx_slv_list (list_code,fetched_at)
);

-- A sanctions/PEP hit or a transaction-monitoring alert for compliance review.
CREATE TABLE psp_aml_alerts (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    alert_ref                    VARCHAR(40) NOT NULL,
    alert_type                   VARCHAR(40) NOT NULL,
    subject_type                 VARCHAR(20) NOT NULL,
    subject_ref                  VARCHAR(120) NOT NULL,
    subject_name                 VARCHAR(300),
    dedupe_key                   VARCHAR(120) NOT NULL,
    matched_entry_id             BIGINT,
    score                        INT NOT NULL DEFAULT 0,
    amount_usd_minor             BIGINT,
    details                      TEXT,
    status                       VARCHAR(20) NOT NULL,
    reviewed_by                  VARCHAR(120),
    review_note                  VARCHAR(2000),
    decided_at                   DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_aml_alerts_alert_ref UNIQUE (alert_ref),
    INDEX idx_aml_status (status,created_at),
    CONSTRAINT uq_aml_dedupe UNIQUE (alert_type,subject_ref,dedupe_key)
);
